// Base64-encoded JetBrains Mono TTF (subset: latin, regular + bold weights),
// sourced from @fontsource/jetbrains-mono. Embedded directly (instead of
// fetched at runtime) so PDF receipts render with the exact same font as
// the on-screen receipt/thermal print (--font-mono in index.css), even
// offline. jsPDF only ships Helvetica/Times/Courier by default, so without
// this, doc.setFont('JetBrains Mono') silently falls back to Helvetica.
export const JETBRAINS_MONO_REGULAR_TTF_BASE64 = '';

export const JETBRAINS_MONO_BOLD_TTF_BASE64 = '';
